#include <stdio.h>
#include <stdlib.h>

void free_matrix(int **matrix, int r) {
    for (int i = 0; i < r; ++i) {
        free(matrix[i]);
    }
    free(matrix);
}

void print_matrix(int **matrix, int r, int c) {
    for (int i = 0; i < r; ++i) {
        for (int j = 0; j < c; ++j) {
            printf("%d", matrix[i][j]);
            if (j < c - 1) printf(" ");
        }
        printf("\n");
    }
}

void read_matrix(FILE *fp, int **matrix, int *r, int *c) {
    fscanf(fp, "%d %d", r, c);
    *matrix = malloc((*r) * sizeof(int*));
    for (int i = 0; i < *r; ++i) {
        (*matrix)[i] = malloc(*c * sizeof(int));
    }
    for (int i = 0; i < *r; ++i) {
        for (int j = 0; j < *c; ++j) {
            fscanf(fp, "%d", &((*matrix)[i][j]));
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s fileA fileB\n", argv[0]);
        return 1;
    }

    FILE *fpA = fopen(argv[1], "r");
    if (!fpA) {
        perror("fopen A");
        return 1;
    }

    FILE *fpB = fopen(argv[2], "r");
    if (!fpB) {
        perror("fopen B");
        fclose(fpA);
        return 1;
    }

    int a_r, a_c;
    read_matrix(fpA, &a, &a_c);

    int b_r, b_c;
    read_matrix(fpB, &b, &b_c);

    if (a_r != b_r || a_c != b_c) {
        fprintf(stderr, "Matrix sizes do not match.\n");
        fclose(fpA);
        fclose(fpB);
        return 1;
    }

    // Allocate matrices
    int **A = malloc(a_r * sizeof(int*));
    for (int i = 0; i < a_r; ++i) {
        A[i] = malloc(a_c * sizeof(int));
    }

    int **B = malloc(b_r * sizeof(int*));
    for (int i = 0; i < b_r; ++i) {
        B[i] = malloc(a_c * sizeof(int)); // same columns as A
    }

    // Read data into matrices
    read_matrix(fpA, &A, &a_c);
    read_matrix(fpB, &B, &b_c);

    // Compute results
    int **sum = malloc(a_r * sizeof(int*));
    for (int i = 0; i < a_r; ++i) {
        sum[i] = malloc(a_c * sizeof(int));
    }

    int **diff = malloc(a_r * sizeof(int*));
    for (int i = 0; i < a_r; ++i) {
        diff[i] = malloc(a_c * sizeof(int));
    }

    int **prod = malloc(a_r * sizeof(int*));
    for (int i = 0; i < a_r; ++i) {
        prod[i] = malloc(a_c * sizeof(int));
    }

    // Calculate sum
    for (int i = 0; i < a_r; ++i) {
        for (int j = 0; j < a_c; ++j) {
            sum[i][j] = A[i][j] + B[i][j];
        }
    }

    // Calculate diff
    for (int i = 0; i < a_r; ++i) {
        for (int j = 0; j < a_c; ++j) {
            diff[i][j] = A[i][j] - B[i][j];
        }
    }

    // Calculate prod
    for (int i = 0; i < a_r; ++i) {
        for (int j = 0; j < a_c; ++j) {
            prod[i][j] = A[i][j] * B[i][j];
        }
    }

    // Output results
    print_matrix(sum, a_r, a_c);
    printf("\n");
    print_matrix(diff, a_r, a_c);
    printf("\n");
    print_matrix(prod, a_r, a_c);

    // Free memory
    free_matrix(A, a_r);
    free_matrix(B, b_r);
    free_matrix(sum, a_r);
    free_matrix(diff, a_r);
    free_matrix(prod, a_r);

    fclose(fpA);
    fclose(fpB);

    return 0;
}

