#include <stdio.h>

#define N 10

int main() {
    int matrix[N][N];

    // Input the matrix elements
    printf("Enter %d x %d matrix elements:\n", N, N);
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            scanf("%d", &matrix[i][j]);
        }
    }

    // Find the row with the minimum element
    int min_row = 0;
    int min_col = 0;
    int min_val = matrix[0][0];

    for (int i = 1; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (matrix[i][j] < min_val) {
                min_val = matrix[i][j];
                min_row = i;
                min_col = j;
            }
        }
    }

    // Swap the first row with the row containing the minimum element
    for (int j = 0; j < N; ++j) {
        int temp = matrix[0][j];
        matrix[0][j] = matrix[min_row][j];
        matrix[min_row][j] = temp;
    }

    // Output the resulting matrix
    printf("\nResultant matrix after swapping:\n");
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            printf("%d ", matrix[i][j]);
        }
        printf("\n");
    }

    return 0;
}
```

