#include <stdio.h>

int main() {
    int m, n;
    printf("Enter dimensions m and n: ");
    scanf("%d %d", &m, &n);

    // Input matrix of size m x n
    int matrix[m][n];
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            printf("Enter element [%d][%d]: ", i, j);
            scanf("%d", &matrix[i][j]);
        }
    }

    // Input vector of size n
    int vector[n];
    for (int i = 0; i < n; ++i) {
        printf("Enter element %d: ", i + 1);
        scanf("%d", &vector[i]);
    }

    // Compute matrix-vector product result (size m)
    int result[m] = {0};
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            result[i] += matrix[i][j] * vector[j];
        }
    }

    // Find maximum value in the resulting vector
    int max_val = result[0];
    for (int i = 1; i < m; ++i) {
        if (result[i] > max_val) {
            max_val = result[i];
        }
    }

    // Output the resulting vector
    printf("%d", result[0]);
    for (int i = 1; i < m; ++i) {
        printf(" %d", result[i]);
    }
    printf("\n");

    // Output maximum value
    printf("%d\n", max_val);

    return 0;
