// 结构体用于存储列的特征值及其原始索引
typedef struct {
    int charact;      // 列特征值（负奇数元素绝对值之和）
    int original_col; // 原始列号
} ColumnInfo;

// 比较函数，用于qsort按特征值升序排序
int compare(const void *a, const void *b) {
    ColumnInfo *c1 = (ColumnInfo *)a;
    ColumnInfo *c2 = (ColumnInfo *)b;
    return c1->charact - c2->charact; // 升序比较
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);

    // 分配并读取矩阵数据
    int **a = (int **)malloc(n * sizeof(int *));
    for (int i = 0; i < n; ++i) {
        a[i] = (int *)malloc(m * sizeof(int));
        for (int j = 0; j < m; ++j) {
            scanf("%d", &a[i][j]);
        }
    }

    // 计算每列的特征值并存储原始索引
    ColumnInfo col_info[m];
    for (int j = 0; j < m; ++j) {
        int sum = 0;
        for (int i = 0; i < n; ++i) {
            if (a[i][j] < 0 && a[i][j] % 2 != 0) { // 负且奇数元素
                sum += abs(a[i][j]);
            }
        }
        col_info[j].charact = sum;
        col_info[j].original_col = j;
    }

    // 按特征值升序排序列信息
    qsort(col_info, m, sizeof(ColumnInfo), compare);

    // 重新排列矩阵列并输出结果
    int **b = (int **)malloc(n * sizeof(int *));
    for (int i = 0; i < n; ++i) {
        b[i] = (int *)malloc(m * sizeof(int));
    }

    for (int i = 0; i < n; ++i) {
        for (int k = 0; k < m; ++k) { // 新列顺序由排序后的col_info决定
            int original_col = col_info[k].original_col;
            b[i][k] = a[i][original_col];
        }
    }

    // 打印结果矩阵
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            printf("%d ", b[i][j]);
        }
        printf("\n");
    }

    // 释放内存
    for (int i = 0; i < n; ++i) {
        free(a[i]);
        free(b[i]);
    }
    free(a);
    free(b);

    return 0;
}

