// 计算子矩阵（去掉第i行和第j列）的行列式
int **minor(int **a, int i, int j, int n) {
    // 分配n-1阶子矩阵的空间
    int **sub = (int **)malloc((n - 1) * sizeof(int *));
    for (int k = 0; k < n - 1; k++) {
        sub[k] = (int *)malloc((n - 1) * sizeof(int));
    }

    // 填充子矩阵元素
    int row = 0;
    for (int r = 0; r < n; r++) {
        if (r == i) continue; // 跳过原i行
        int col = 0;
        for (int c = 0; c < n; c++) {
            if (c == j) continue; // 跳过原j列
            sub[row][col] = a[r][c];
            col++;
        }
        row++;
    }

    return sub;
}

// 计算n阶矩阵的行列式（递归展开法）
int det(int **a, int n) {
    if (n == 1) return a[0][0]; // 一阶行列式
    if (n == 2) return a[0][0] * a[1][1] - a[0][1] * a[1][0]; // 二阶行列式

    int result = 0;
    for (int j = 0; j < n; j++) {
        // 代数余子式的符号：(-1)^(i+j)，这里i=0，故符号为(-1)^j
        int sign = ((j % 2 == 0) ? 1 : -1);
        result += sign * a[0][j] * det(minor(a, 0, j, n), n - 1);
    }
    return result;
}

int main() {
