        matrix[i] = (int *)malloc(n * sizeof(int));
    }

    // 输入矩阵元素
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &matrix[i][j]);
        }
    }

    int determinant = det(matrix, n); // 计算行列式

    printf("%d\n", determinant); // 输出结果

    // 释放动态分配的内存
