#include <stdio.h>

int main() {
    int N;
    scanf("%d", &N);

    if (N < 2) {
        return 0; // 或者直接输出空行？不过题目要求如果无则输出空字符串，所以这里不打印任何内容。
    }

    int is_prime[N + 1];
    for (int i = 0; i <= N; i++) {
        is_prime[i] = 1;
    }

    for (int p = 2; p * p <= N; p++) {
        if (is_prime[p]) {
            for (int i = p * p; i <= N; i += p) {
                is_prime[i] = 0;
            }
        }
    }

    int first = 1;
    for (int i = 2; i <= N; i++) {
        if (is_prime[i]) {
            if (!first) printf(" ");
            else first = 0;
            printf("%d", i);
        }
    }

    return 0;
}
```

